func get_camera_impulse_telemetry():
				return _impulse_telemetry

func _impulse_poll_events():
				var buffer = stats.get("_spine_last_events")
				if buffer == null or buffer.size() == 0:
								return
				for event in buffer:
								var seq = int(event.get("seq", 0))
								if seq <= _impulse_last_seq:
												continue
								_impulse_last_seq = seq
								_impulse_telemetry.events += 1
								var event_class = event.get("event_class", "")
								if event_class == "direct_hit":
												_impulse_telemetry.blocked_direct_hits += 1
												continue
								if event_class == "dot_tick":
												_impulse_telemetry.blocked_dot_ticks += 1
												continue
								if event_class == "kill":
												_impulse_telemetry.blocked_kill_records += 1
												continue
								if event_class == "crit":
												_impulse_telemetry.crits += 1
												_impulse_add(IMPULSE_CRIT_AMPLITUDE, false)
												continue
								if event_class == "impulse":
												var kind = event.get("impulse_kind", "")
												var amplitude = float(event.get("amplitude", 0.0))
												if kind == "kill":
																_impulse_telemetry.kills += 1
																if event.get("is_elite", false):
																				_impulse_telemetry.elite_kills += 1
																# B3-S5 FIX 2026-08-20: kill camera impulse disabled per HUMAN S5 - count only
														_impulse_telemetry.blocked_kill_pulses += 1
												elif kind == "heavy":
																_impulse_telemetry.heavies += 1
																_impulse_add(amplitude, false)

func _impulse_add(added_amplitude, is_kill):
				var now = int(OS.get_ticks_msec())
				var new_group = true
				if _impulse_amplitude > 0.0 and now - _impulse_group_started_ms <= IMPULSE_WINDOW_MS:
								new_group = false
				elif is_kill and _impulse_cluster_kills > 0 and now - _impulse_last_kill_ms <= IMPULSE_WINDOW_MS:
								new_group = false
				if new_group:
								_impulse_group_started_ms = now
								_impulse_angle = randf() * 2.0 * PI
								if not is_kill:
												_impulse_cluster_kills = 0
				if is_kill:
								var since_last_kill = now - _impulse_last_kill_ms
								_impulse_cluster_kills += 1
								_impulse_last_kill_ms = now
								if _impulse_cluster_kills > 1 and since_last_kill <= IMPULSE_WINDOW_MS:
												_impulse_telemetry.clusters += 1
												var appendix = min(IMPULSE_CLUSTER_APPENDIX * float(_impulse_cluster_kills - 1), IMPULSE_CLUSTER_APPENDIX_CAP)
												added_amplitude = min(added_amplitude + appendix, IMPULSE_BUDGET_MAX)
				if _impulse_amplitude + added_amplitude > IMPULSE_BUDGET_MAX:
								_impulse_telemetry.capped_amplitude += 1
				_impulse_amplitude = min(_impulse_amplitude + added_amplitude, IMPULSE_BUDGET_MAX)
				_impulse_telemetry.impulses += 1

func _impulse_decay(delta):
				if _impulse_amplitude > 0.0:
								_impulse_amplitude = max(0.0, _impulse_amplitude - IMPULSE_DECAY_PER_SEC * delta)
								if _impulse_amplitude <= 0.0:
												_impulse_amplitude = 0.0

func _impulse_apply_offset():
				var dir = Vector2(cos(_impulse_angle), sin(_impulse_angle))
				var offset = dir * _impulse_amplitude
				if offset.length() > IMPULSE_MAX_OFFSET:
								offset = offset.normalized() * IMPULSE_MAX_OFFSET
								_impulse_telemetry.capped_offset += 1
				camera2d.offset = offset

